-- Vorrats-Aufgaben (rollend-2) in bestehende Flüge einfügen: 116 Aufgaben, 6 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (6, 'gleichungen.einfach', 599, 20, $auf$[{"l": "waage", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "x + 8 = 21 als Waage: Links bleibt nur x übrig, wenn du 8 wegnimmst. Dasselbe nimmst du rechts weg. Rechts bleiben dann ①. Also ist x = ①. Dann ist 3 · x = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [13, 39]}, "h": "Was du links wegnimmst, nimmst du auch rechts weg.", "w": "21 − 8 = 13, also x = 13. 3 · 13 = 39.", "form": "lueckenweg", "zaehlt": "nein", "r": 600}, {"l": "zwei_schritte", "t": "umkehren", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Löse 4 · x + 7 = 31 rückwärts. Erst 31 − 7 = ①. Dann ① : 4 = ②. Also x = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [24, 6]}, "h": "Der letzte Schritt war „+ 7“. Den machst du zuerst rückgängig.", "w": "31 − 7 = 24, dann 24 : 4 = 6. Probe: 4 · 6 + 7 = 31.", "form": "lueckenweg", "zaehlt": "nein", "r": 601}, {"l": "zwei_schritte", "t": "umkehren", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Jemand löst 5 · x − 3 = 32 so: Schritt 1: 32 : 5. Schritt 2: Ergebnis + 3. Was ist falsch?"}, "a": ["Es müsste − 3 statt + 3 heißen.", "Es müsste · 5 statt : 5 heißen.", "Nichts, der Weg stimmt.", "Die Reihenfolge: erst + 3, dann : 5."], "o": {"index": 3}, "h": "Welcher Schritt kam in der Gleichung zuletzt?", "w": "Zuletzt wurde 3 abgezogen. Das wird zuerst rückgängig gemacht: 32 + 3 = 35, dann 35 : 5 = 7.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 602}, {"l": "probe", "t": "verstehen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Wie machst du die Einsetzprobe für x = 9 bei der Gleichung 6 · x − 14 = 40?"}, "a": ["40 für x einsetzen", "9 für x einsetzen und beide Seiten vergleichen", "9 und 40 zusammenzählen", "6 für x einsetzen, weil die 6 vor dem x steht"], "o": {"index": 1}, "h": "Eine Lösung macht beide Seiten gleich.", "w": "Einsetzen: 6 · 9 − 14 = 40. Beide Seiten sind gleich, also ist 9 die Lösung.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 603}, {"l": "ohne_loesung", "t": "loesbarkeit", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Woran erkennst du, dass 6 · x + 20 = 14 in ℕ keine Lösung hat?"}, "a": ["14 ist nicht durch 6 teilbar.", "Rückwärts müsstest du 14 − 20 rechnen. Das geht in ℕ nicht.", "20 ist größer als 6.", "Links steht ein Plus."], "o": {"index": 1}, "h": "Rechne den ersten Schritt rückwärts.", "w": "Rückwärts: 14 − 20. Das Ergebnis läge unter 0. In ℕ gibt es deshalb keine Lösung.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 604}, {"l": "zwei_schritte", "t": "umkehren", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ich denke mir eine Zahl, nehme sie mal 6 und ziehe 12 ab. Ich erhalte 48. Welche Zahl habe ich mir gedacht?"}, "o": {"wert": 10}, "h": "Rechne rückwärts. Was kam zuletzt?", "w": "Zuletzt wurde 12 abgezogen: 48 + 12 = 60. Davor mal 6: 60 : 6 = 10.", "form": "umkehren", "zaehlt": "ja", "r": 605}, {"l": "waage", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Zwei Wege für 3 · x + 12 = 30. Weg A: erst − 12, dann : 3. Weg B: erst beide Seiten durch 3 teilen. Dann steht da x + ? = 10. Welche Zahl steht für das Fragezeichen?"}, "o": {"wert": 4}, "h": "Beim Teilen wird links jeder Summand geteilt.", "w": "Geteilt durch 3: aus 3 · x wird x, aus 12 wird 4, aus 30 wird 10. Also x + 4 = 10 und x = 6 – wie bei Weg A.", "form": "zwei_wege", "zaehlt": "ja", "r": 606}, {"l": "waage", "t": "verstehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "luecken", "f": {"text": "Links liegen drei gleiche Säckchen mit je x Kugeln und 4 einzelne Kugeln. Rechts liegen 19 Kugeln. Die Waage ist im Gleichgewicht. Schreibe die Gleichung und löse sie.", "schablone": "□ · x + □ = □; x = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [3, 4, 19, 5]}, "h": "Säckchen sind das x. Einzelne Kugeln sind Zahlen.", "w": "3 · x + 4 = 19. Auf beiden Seiten 4 weg: 3 · x = 15. Geteilt durch 3: x = 5.", "form": "bruecke", "zaehlt": "ja", "r": 607}, {"l": "aufstellen", "t": "anwenden", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "„Das Vierfache einer Zahl, vermindert um 5, ergibt 23.“ Welche Gleichung passt?"}, "a": ["4 · (x − 5) = 23", "5 − 4 · x = 23", "4 · x − 5 = 23", "x : 4 − 5 = 23"], "o": {"index": 2}, "h": "Übersetze Stück für Stück: erst „das Vierfache“, dann „vermindert um 5“.", "w": "Das Vierfache: 4 · x. Vermindert um 5: 4 · x − 5. Ergibt 23: 4 · x − 5 = 23. (Lösung: x = 7.)", "form": "bruecke", "zaehlt": "ja", "r": 608}, {"l": "aufstellen", "t": "anwenden", "p": "uebung", "s": 2, "g": "umkehr", "y": "auswahl", "f": {"text": "Welcher Satz passt zur Gleichung (x + 6) · 3 = 27?"}, "a": ["Das Dreifache einer Zahl, vermehrt um 6, ergibt 27.", "Zu einer Zahl wird 6 addiert. Das Dreifache dieser Summe ist 27.", "Eine Zahl wird durch 3 geteilt und um 6 vermehrt. Das ergibt 27."], "o": {"index": 1}, "h": "Was passiert wegen der Klammer zuerst?", "w": "Die Klammer kommt zuerst: x + 6. Dann mal 3. Der erste Satz gehört zu 3 · x + 6 = 27.", "form": "umkehren", "zaehlt": "ja", "r": 609}, {"l": "probe", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "Nora löst 8 · x − 6 = 50 und erhält x = 6. Mach die Probe: Mit x = 6 ergibt die linke Seite ①. Das ist nicht 50. Die richtige Lösung ist x = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [42, 7]}, "h": "Setze 6 ein. Löse dann selbst rückwärts.", "w": "8 · 6 − 6 = 42, also stimmt 6 nicht. Rückwärts: 50 + 6 = 56, 56 : 8 = 7.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 610}, {"l": "probe", "t": "verstehen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Die Gleichung 4 · x + □ = 26 soll die Lösung x = 5 haben. Welche Zahl gehört in das Kästchen?"}, "o": {"wert": 6}, "h": "Setze 5 für x ein.", "w": "4 · 5 = 20. Bis 26 fehlen 6.", "form": "umkehren", "zaehlt": "ja", "r": 611}, {"l": "zwei_schritte", "t": "umkehren", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "(x : 3 + 4) · 2 = 20. Rechne rückwärts: Welche Zahl ist x?"}, "o": {"wert": 18}, "h": "Drei Schritte. Der letzte war „· 2“.", "w": "20 : 2 = 10. Dann 10 − 4 = 6. Dann 6 · 3 = 18. Probe: 18 : 3 + 4 = 10, mal 2 ist 20.", "form": "umkehren", "zaehlt": "ja", "r": 612}, {"l": "ohne_loesung", "t": "loesbarkeit", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Tom sagt: „7 · x + 3 = 40 hat in ℕ keine Lösung.“ Stimmt das?"}, "a": ["Ja: 40 − 3 = 37, und 37 lässt sich nicht ohne Rest durch 7 teilen.", "Nein: x = 5 ist eine Lösung.", "Nein: Jede Gleichung hat eine Lösung.", "Ja: weil 3 kleiner ist als 7."], "o": {"index": 0}, "h": "Rechne rückwärts und schau, ob das Teilen aufgeht.", "w": "40 − 3 = 37. 37 : 7 geht nicht auf (7 · 5 = 35, 7 · 6 = 42). In ℕ gibt es keine Lösung.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 613}, {"l": "aufstellen", "t": "anwenden", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Drei Freunde kaufen zusammen ein Geschenk für 31 €. Jeder zahlt gleich viel. Die fehlenden 4 € kommen aus der Klassenkasse. Wie viel Euro zahlt jeder?"}, "o": {"wert": 9, "einheit": "€"}, "h": "Nenne den Betrag eines Freundes x und stelle eine Gleichung auf.", "w": "3 · x + 4 = 31. Rückwärts: 31 − 4 = 27, 27 : 3 = 9.", "form": "anwenden", "zaehlt": "ja", "r": 614}, {"l": "probe", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "bedingung", "f": {"text": "Nenne eine natürliche Zahl x, für die 3 · x + 2 größer als 20 und kleiner als 30 ist.", "felder": [{"art": "ganz"}]}, "o": {"bedingungen": [{"name": "größer als 20", "pruefe": [">", ["+", ["*", 3, "$1"], 2], 20], "zeige": ["+", ["*", 3, "$1"], 2], "hinweis": "Mit deiner Zahl hat 3 · x + 2 den Wert {}."}, {"name": "kleiner als 30", "pruefe": ["<", ["+", ["*", 3, "$1"], 2], 30], "zeige": ["+", ["*", 3, "$1"], 2], "hinweis": "Mit deiner Zahl hat 3 · x + 2 den Wert {}."}], "beispiel": [7], "gut": [[8], [9]], "gegenbeispiele": [{"werte": [6], "verletzt": "größer als 20"}, {"werte": [10], "verletzt": "kleiner als 30"}, {"werte": [0], "verletzt": "größer als 20"}]}, "h": "Setze eine Zahl ein und rechne aus.", "w": "Es passen 7, 8 und 9: Sie ergeben 23, 26 und 29.", "form": "viele_antworten", "zaehlt": "ja", "r": 615}, {"l": "aufstellen", "t": "anwenden", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Erfinde ein Zahlenrätsel zur gedachten Zahl 7: „Ich nehme meine Zahl mal □ und zähle □ dazu. Ich erhalte □.“ Die erste Zahl soll größer als 1 sein, die zweite größer als 0.", "felder": [{"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "erste Zahl größer als 1", "pruefe": [">", "$1", 1], "zeige": "$1", "hinweis": "Deine erste Zahl ist {}."}, {"name": "zweite Zahl größer als 0", "pruefe": [">", "$2", 0], "zeige": "$2", "hinweis": "Deine zweite Zahl ist {}."}, {"name": "das Rätsel stimmt für die 7", "pruefe": ["=", ["+", ["*", "$1", 7], "$2"], "$3"], "zeige": ["+", ["*", "$1", 7], "$2"], "hinweis": "Mit der 7 kommt bei deinem Rätsel {} heraus."}], "beispiel": [3, 4, 25], "gut": [[2, 1, 15]], "gegenbeispiele": [{"werte": [1, 4, 11], "verletzt": "erste Zahl größer als 1"}, {"werte": [3, 0, 21], "verletzt": "zweite Zahl größer als 0"}, {"werte": [3, 4, 24], "verletzt": "das Rätsel stimmt für die 7"}]}, "h": "Rechne dein Rätsel mit der 7 durch.", "w": "Zum Beispiel mal 3 und plus 4: 7 · 3 + 4 = 25.", "form": "viele_antworten", "zaehlt": "ja", "r": 616}, {"l": "waage", "t": "verstehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "bedingung", "f": {"text": "Links liegen einige gleiche Säckchen und 2 einzelne Kugeln, rechts 20 Kugeln. Die Waage ist im Gleichgewicht. Nenne eine mögliche Zahl der Säckchen und die Zahl der Kugeln in jedem Säckchen. Beide Zahlen sollen größer als 1 sein.", "felder": [{"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "beide größer als 1", "pruefe": [">", ["min", "$alle"], 1], "zeige": ["min", "$alle"], "hinweis": "Deine kleinere Zahl ist {}."}, {"name": "Waage im Gleichgewicht", "pruefe": ["=", ["+", ["*", "$1", "$2"], 2], 20], "zeige": ["+", ["*", "$1", "$2"], 2], "hinweis": "Links liegen bei dir {} Kugeln."}], "beispiel": [3, 6], "gut": [[2, 9], [9, 2]], "gegenbeispiele": [{"werte": [1, 18], "verletzt": "beide größer als 1"}, {"werte": [3, 5], "verletzt": "Waage im Gleichgewicht"}, {"werte": [4, 5], "verletzt": "Waage im Gleichgewicht"}]}, "h": "Wie viele Kugeln müssen in allen Säckchen zusammen sein?", "w": "In den Säckchen sind zusammen 18 Kugeln. Es passen 2 Säckchen mit 9, 3 mit 6, 6 mit 3 oder 9 mit 2.", "form": "viele_antworten", "zaehlt": "ja", "r": 617}, {"l": "ohne_loesung", "t": "loesbarkeit", "p": "uebung", "s": 3, "g": "parameter", "y": "bedingung", "f": {"text": "Setze eine Zahl zwischen 1 und 19 ein, sodass die Gleichung 3 · x + □ = 20 in ℕ keine Lösung hat.", "felder": [{"art": "ganz"}]}, "o": {"bedingungen": [{"name": "zwischen 1 und 19", "pruefe": ["und", [">=", "$1", 1], ["<=", "$1", 19]], "zeige": "$1", "hinweis": "Deine Zahl ist {}."}, {"name": "keine Lösung in ℕ", "pruefe": ["nicht", ["teilbar", ["-", 20, "$1"], 3]], "zeige": ["/", ["-", 20, "$1"], 3], "hinweis": "Mit deiner Zahl ist x = {} eine Lösung."}], "beispiel": [4], "gut": [[1], [19]], "gegenbeispiele": [{"werte": [25], "verletzt": "zwischen 1 und 19"}, {"werte": [2], "verletzt": "keine Lösung in ℕ"}, {"werte": [0], "verletzt": "zwischen 1 und 19"}, {"werte": [17], "verletzt": "keine Lösung in ℕ"}]}, "h": "Rechne rückwärts: Was muss sich dann durch 3 teilen lassen?", "w": "Rückwärts bleibt 20 minus deine Zahl. Lässt sich das nicht ohne Rest durch 3 teilen, gibt es keine Lösung. Zum Beispiel 4: 16 : 3 geht nicht auf.", "form": "viele_antworten", "zaehlt": "ja", "r": 618}, {"l": "zwei_schritte", "t": "umkehren", "p": "uebung", "s": 3, "g": "parameter", "y": "bedingung", "f": {"text": "Baue eine Gleichung der Form □ · x − □ = □ mit der Lösung x = 6. Die drei Zahlen sollen verschieden und alle größer als 1 sein.", "felder": [{"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "alle größer als 1", "pruefe": [">", ["min", "$alle"], 1], "zeige": ["min", "$alle"], "hinweis": "Deine kleinste Zahl ist {}."}, {"name": "verschieden", "pruefe": ["verschieden", "$alle"], "hinweis": "Die drei Zahlen sollen verschieden sein."}, {"name": "x = 6 ist die Lösung", "pruefe": ["=", ["-", ["*", "$1", 6], "$2"], "$3"], "zeige": ["-", ["*", "$1", 6], "$2"], "hinweis": "Mit x = 6 hat deine linke Seite den Wert {}."}], "beispiel": [3, 4, 14], "gut": [[2, 3, 9], [5, 10, 20]], "gegenbeispiele": [{"werte": [2, 1, 11], "verletzt": "alle größer als 1"}, {"werte": [3, 3, 15], "verletzt": "verschieden"}, {"werte": [3, 4, 15], "verletzt": "x = 6 ist die Lösung"}]}, "h": "Wähle die ersten zwei Zahlen und rechne mit x = 6 die linke Seite aus.", "w": "Zum Beispiel 3 · x − 4 = 14, denn 3 · 6 − 4 = 14.", "form": "viele_antworten", "zaehlt": "ja", "r": 619}]$auf$::jsonb),
    (13, 'daten.darstellen', 582, 19, $auf$[{"l": "absolute_haeufigkeit", "t": "absolute_haeufigkeit", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Würfe: 3, 5, 3, 6, 1, 3, 5, 1, 6, 3. Die 3 kommt ①-mal vor, die 5 kommt ②-mal vor. Alle Würfe zusammen: ③. Die 3 hat die relative Häufigkeit ① von ③, das sind ④ %.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [4, 2, 10, 40]}, "h": "Streiche jede gezählte Zahl ab.", "w": "Die 3 steht viermal, die 5 zweimal. Es sind 10 Würfe. 4 von 10 sind 40 %.", "form": "lueckenweg", "zaehlt": "nein", "r": 583}, {"l": "relative_haeufigkeit", "t": "relative_haeufigkeit", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Von 40 Kindern kommen 10 mit dem Rad und 20 zu Fuß. Der Anteil Rad ist 10 von 40, gekürzt 1 von ①. In Prozent: 10 · 100 : 40 = ②. Zu Fuß sind es 20 · 100 : 40 = ③ %. Alle anderen zusammen: 100 − ② − ③ = ④ %.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [4, 25, 50, 25]}, "h": "Relative Häufigkeit ist Anzahl durch Gesamtzahl.", "w": "40 : 10 = 4. 10 von 40 sind 25 %. 20 von 40 sind 50 %. Der Rest ist 100 − 25 − 50 = 25 %.", "form": "lueckenweg", "zaehlt": "nein", "r": 584}, {"l": "relative_haeufigkeit", "t": "relative_haeufigkeit", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "In einer Klasse sind 12 Mädchen und 18 Jungen. Tim rechnet für den Anteil der Mädchen 12/18. Was ist falsch?"}, "a": ["Er müsste 18/12 rechnen.", "Er müsste 12 + 18 rechnen.", "Er teilt durch die Zahl der Jungen statt durch alle 30 Kinder.", "Nichts, 12/18 stimmt."], "o": {"index": 2}, "h": "Wodurch wird bei der relativen Häufigkeit geteilt?", "w": "Geteilt wird durch die Gesamtzahl: 12 + 18 = 30. Der Anteil ist 12/30 = 2/5, das sind 40 %.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 585}, {"l": "kreisdiagramm", "t": "kreisdiagramm", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Ein Anteil von 25 % soll im Kreisdiagramm gezeichnet werden. Wie findest du den Winkel?"}, "a": ["25 · 360° rechnen", "ein Viertel von 360° nehmen", "25° abtragen", "360° : 25 rechnen"], "o": {"index": 1}, "h": "25 % sind welcher Bruchteil?", "w": "25 % sind ein Viertel. Ein Viertel von 360° sind 90°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 586}, {"l": "tabelle_auswerten", "t": "tabelle_auswerten", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt, wie die Kinder einer Schule zur Schule kommen. Wie viel Prozent kommen mit dem Bus?", "grafik": {"typ": "tabelle", "kopf": ["Weg", "zu Fuß", "Rad", "Bus", "Auto"], "zeilen": [["Anzahl", "8", "10", "16", "6"]]}}, "o": {"wert": 40, "einheit": "%"}, "h": "Bilde zuerst die Summe aller Anzahlen.", "w": "Zusammen 8 + 10 + 16 + 6 = 40 Kinder. Bus: 16 von 40, das sind 40 %.", "form": "bruecke", "zaehlt": "ja", "r": 587}, {"l": "relative_haeufigkeit", "t": "relative_haeufigkeit", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "25 % der befragten Kinder nennen „Hund“ als Lieblingstier. Das sind 7 Kinder. Wie viele Kinder wurden befragt?"}, "o": {"wert": 28}, "h": "25 % sind ein Viertel. Wie viele Viertel hat das Ganze?", "w": "7 Kinder sind ein Viertel. Alle Kinder sind vier Viertel: 4 · 7 = 28.", "form": "umkehren", "zaehlt": "ja", "r": 588}, {"l": "absolute_haeufigkeit", "t": "absolute_haeufigkeit", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Bei 30 Würfen fiel die 6 genau 4-mal. Die 1 fiel doppelt so oft wie die 6. Wie oft fielen die anderen vier Zahlen zusammen?"}, "o": {"wert": 18}, "h": "Alle Häufigkeiten zusammen ergeben die Zahl der Würfe.", "w": "Die 6 viermal, die 1 achtmal. Für die anderen bleiben 30 − 4 − 8 = 18 Würfe.", "form": "umkehren", "zaehlt": "ja", "r": 589}, {"l": "saeulendiagramm", "t": "saeulendiagramm", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "In einem Säulendiagramm steht 1 cm für 4 Kinder. Eine Säule ist 3,5 cm hoch. Für wie viele Kinder steht sie?"}, "o": {"wert": 14}, "h": "Jeder Zentimeter steht für 4 Kinder.", "w": "3,5 · 4 = 14 Kinder.", "form": "umkehren", "zaehlt": "ja", "r": 590}, {"l": "saeulendiagramm", "t": "saeulendiagramm", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Das Diagramm zeigt die Lieblingstiere einer Klasse. Wie viele Kinder wurden insgesamt befragt?", "grafik": {"typ": "saeulen", "einheit": "Kinder", "werte": [{"name": "Hund", "wert": 9}, {"name": "Katze", "wert": 7}, {"name": "Pferd", "wert": 5}, {"name": "Hase", "wert": 3}], "y_start": 0, "zahlen": false}}, "o": {"wert": 24}, "h": "Lies jede Säule an der Achse ab.", "w": "Hund 9, Katze 7, Pferd 5, Hase 3. Zusammen 24 Kinder.", "form": "bruecke", "zaehlt": "ja", "r": 591}, {"l": "kreisdiagramm", "t": "kreisdiagramm", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "Von 24 Kindern spielen 6 Fußball. Zwei Wege zum Winkel im Kreisdiagramm. Weg A: 6 von 24 ist ein Viertel, also ein Viertel von 360°. Weg B: Auf ein Kind kommen 360° : 24 = ①°, auf 6 Kinder ②°.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [15, 90]}, "h": "Beide Wege müssen denselben Winkel ergeben.", "w": "360° : 24 = 15° je Kind. 6 · 15° = 90°. Weg A: ein Viertel von 360° sind auch 90°.", "form": "zwei_wege", "zaehlt": "ja", "r": 592}, {"l": "irrefuehrend", "t": "irrefuehrend", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Das Diagramm zeigt die Besucher eines Schwimmbads. Die Säule für Juli ist doppelt so hoch wie die für Juni. Was stimmt?", "grafik": {"typ": "saeulen", "einheit": "Besucher", "werte": [{"name": "Juni", "wert": 520}, {"name": "Juli", "wert": 540}], "y_start": 500, "zahlen": true}}, "a": ["Im Juli kamen doppelt so viele Besucher wie im Juni.", "Im Juli kamen 20 Besucher mehr. Die Achse beginnt erst bei 500.", "Im Juli kamen 40 Besucher mehr.", "Die Zahlen im Diagramm sind falsch."], "o": {"index": 1}, "h": "Lies Achse und Zahlen. Wo beginnt die Achse?", "w": "Juni 520, Juli 540: nur 20 Besucher mehr. Weil die Achse bei 500 beginnt, sind die Säulen 20 und 40 hoch – das sieht nach „doppelt“ aus.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 593}, {"l": "irrefuehrend", "t": "irrefuehrend", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Zwei gleich große Diagramme zeigen dieselben Zahlen: 48 und 52 Stimmen. Bei Diagramm A beginnt die Achse bei 0, bei Diagramm B bei 46. Was stimmt?"}, "a": ["In A wirkt der Unterschied größer: Dort ist die zweite Säule 3-mal so hoch.", "In beiden wirkt der Unterschied gleich groß.", "In B wirkt der Unterschied größer: Dort ist die zweite Säule doppelt so hoch.", "In B wirkt der Unterschied größer: Dort ist die zweite Säule 3-mal so hoch."], "o": {"index": 3}, "h": "Wie hoch sind die Säulen in B? Zieh den Achsenanfang ab.", "w": "In B sind die Säulen 48 − 46 = 2 und 52 − 46 = 6 hoch. 6 ist das Dreifache von 2. In A sind sie fast gleich hoch.", "form": "zwei_wege", "zaehlt": "ja", "r": 594}, {"l": "tabelle_auswerten", "t": "tabelle_auswerten", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "In der Tabelle fehlen zwei Zahlen. Zusammen wurden 50 Stimmen abgegeben, und „Blau“ hat 30 % aller Stimmen. Wie viele Stimmen hat „Grün“?", "grafik": {"typ": "tabelle", "kopf": ["Farbe", "Rot", "Blau", "Grün", "Gelb"], "zeilen": [["Stimmen", "12", "?", "?", "9"]]}}, "o": {"wert": 14}, "h": "Rechne zuerst die Stimmen für Blau aus.", "w": "Blau: 30 % von 50 sind 15. Grün: 50 − 12 − 15 − 9 = 14.", "form": "umkehren", "zaehlt": "ja", "r": 595}, {"l": "kreisdiagramm", "t": "kreisdiagramm", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Das Kreisdiagramm zeigt, wie 60 Kinder ihre Pause verbringen. Wie viele Kinder spielen Fangen?", "grafik": {"typ": "kreisdiagramm", "einheit": " %", "werte": [{"name": "Fangen", "wert": 35}, {"name": "Reden", "wert": 40}, {"name": "Ball", "wert": 25}], "zahlen": true}}, "o": {"wert": 21}, "h": "Der Anteil steht im Diagramm. Das Ganze sind 60 Kinder.", "w": "35 % von 60: 10 % sind 6, 5 % sind 3. Zusammen 3 · 6 + 3 = 21 Kinder.", "form": "anwenden", "zaehlt": "ja", "r": 596}, {"l": "relative_haeufigkeit", "t": "relative_haeufigkeit", "p": "uebung", "s": 1, "g": "direkt", "y": "bedingung", "f": {"text": "In einer Klasse sind zwischen 20 und 30 Kinder. Genau ein Viertel von ihnen trägt eine Brille. Nenne eine mögliche Zahl der Kinder und die Zahl der Kinder mit Brille.", "felder": [{"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "zwischen 20 und 30 Kinder", "pruefe": ["und", [">=", "$1", 20], ["<=", "$1", 30]], "zeige": "$1", "hinweis": "Deine Klasse hat {} Kinder."}, {"name": "ein Viertel trägt eine Brille", "pruefe": ["=", ["*", 4, "$2"], "$1"], "zeige": ["*", 4, "$2"], "hinweis": "Das Vierfache deiner Brillen-Zahl ist {}."}], "beispiel": [24, 6], "gut": [[20, 5], [28, 7]], "gegenbeispiele": [{"werte": [32, 8], "verletzt": "zwischen 20 und 30 Kinder"}, {"werte": [24, 8], "verletzt": "ein Viertel trägt eine Brille"}, {"werte": [22, 5], "verletzt": "ein Viertel trägt eine Brille"}]}, "h": "Ein Viertel heißt: Viermal so viele Kinder sind die ganze Klasse.", "w": "Die Kinderzahl muss durch 4 teilbar sein: 20 und 5, 24 und 6 oder 28 und 7.", "form": "viele_antworten", "zaehlt": "ja", "r": 597}, {"l": "absolute_haeufigkeit", "t": "absolute_haeufigkeit", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "bedingung", "f": {"text": "Ein Glücksrad mit vier Farben wird 20-mal gedreht. Erfinde ein mögliches Ergebnis: Wie oft kam Rot, Blau, Grün, Gelb? Jede Farbe soll mindestens einmal vorkommen, und Rot soll öfter vorkommen als jede andere Farbe.", "felder": [{"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "jede Farbe mindestens einmal", "pruefe": [">=", ["min", "$alle"], 1], "zeige": ["min", "$alle"], "hinweis": "Deine kleinste Anzahl ist {}."}, {"name": "zusammen 20 Drehungen", "pruefe": ["=", ["summe", "$alle"], 20], "zeige": ["summe", "$alle"], "hinweis": "Zusammen sind es bei dir {} Drehungen."}, {"name": "Rot am häufigsten", "pruefe": ["und", [">", "$1", "$2"], [">", "$1", "$3"], [">", "$1", "$4"]], "zeige": "$1", "hinweis": "Rot kam bei dir {}-mal. Eine andere Farbe kam genauso oft oder öfter."}], "beispiel": [8, 5, 4, 3], "gut": [[17, 1, 1, 1], [6, 5, 5, 4]], "gegenbeispiele": [{"werte": [10, 0, 5, 5], "verletzt": "jede Farbe mindestens einmal"}, {"werte": [8, 5, 4, 4], "verletzt": "zusammen 20 Drehungen"}, {"werte": [5, 5, 5, 5], "verletzt": "Rot am häufigsten"}]}, "h": "Alle vier Häufigkeiten zusammen ergeben die Zahl der Drehungen.", "w": "Zum Beispiel 8, 5, 4 und 3: zusammen 20, und die 8 ist am größten.", "form": "viele_antworten", "zaehlt": "ja", "r": 598}, {"l": "kreisdiagramm", "t": "kreisdiagramm", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Ein Kreisdiagramm hat drei Teile. Nenne drei verschiedene Winkel in Grad, die zusammen ein Kreisdiagramm ergeben. Der größte Teil soll genau die Hälfte des Kreises sein.", "felder": [{"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "jeder Winkel größer als 0", "pruefe": [">", ["min", "$alle"], 0], "zeige": ["min", "$alle"], "hinweis": "Dein kleinster Winkel hat {}°."}, {"name": "verschieden", "pruefe": ["verschieden", "$alle"], "hinweis": "Die drei Winkel sollen verschieden sein."}, {"name": "zusammen ein voller Kreis", "pruefe": ["=", ["summe", "$alle"], 360], "zeige": ["summe", "$alle"], "hinweis": "Deine Winkel ergeben zusammen {}°."}, {"name": "größter Teil ist die Hälfte", "pruefe": ["=", ["max", "$alle"], 180], "zeige": ["max", "$alle"], "hinweis": "Dein größter Winkel hat {}°."}], "beispiel": [180, 100, 80], "gut": [[1, 179, 180]], "gegenbeispiele": [{"werte": [180, 200, -20], "verletzt": "jeder Winkel größer als 0"}, {"werte": [180, 90, 90], "verletzt": "verschieden"}, {"werte": [180, 100, 70], "verletzt": "zusammen ein voller Kreis"}, {"werte": [200, 100, 60], "verletzt": "größter Teil ist die Hälfte"}]}, "h": "Wie viel Grad hat der ganze Kreis, wie viel die Hälfte?", "w": "Die Hälfte sind 180°. Die anderen beiden Winkel ergeben zusammen 180° und sind verschieden, zum Beispiel 100° und 80°.", "form": "viele_antworten", "zaehlt": "ja", "r": 599}, {"l": "saeulendiagramm", "t": "saeulendiagramm", "p": "uebung", "s": 3, "g": "parameter", "y": "bedingung", "f": {"text": "Zwei Säulen stehen für 12 und für 30 Kinder. Wähle einen Maßstab: 1 cm steht für □ Kinder. Beide Säulen sollen eine ganze Zahl von Zentimetern hoch sein, und die höhere Säule soll höchstens 10 cm hoch werden.", "felder": [{"art": "ganz"}]}, "o": {"bedingungen": [{"name": "mindestens 1 Kind je Zentimeter", "pruefe": [">=", "$1", 1], "zeige": "$1", "hinweis": "Deine Zahl ist {}."}, {"name": "beide Höhen in ganzen Zentimetern", "pruefe": ["und", ["teilbar", 12, "$1"], ["teilbar", 30, "$1"]], "zeige": ["/", 12, "$1"], "hinweis": "Die Säule für 12 Kinder wird bei dir {} cm hoch. Prüfe auch die andere."}, {"name": "höhere Säule höchstens 10 cm", "pruefe": ["<=", ["/", 30, "$1"], 10], "zeige": ["/", 30, "$1"], "hinweis": "Deine höhere Säule wird {} cm hoch."}], "beispiel": [3], "gut": [[6]], "gegenbeispiele": [{"werte": [0], "verletzt": "mindestens 1 Kind je Zentimeter"}, {"werte": [5], "verletzt": "beide Höhen in ganzen Zentimetern"}, {"werte": [2], "verletzt": "höhere Säule höchstens 10 cm"}, {"werte": [4], "verletzt": "beide Höhen in ganzen Zentimetern"}]}, "h": "Säulenhöhe ist Anzahl durch Maßstab.", "w": "Die Zahl muss 12 und 30 teilen: 1, 2, 3 oder 6. Bei 1 und 2 wird die höhere Säule zu hoch (30 cm, 15 cm). Es passen 3 und 6.", "form": "viele_antworten", "zaehlt": "ja", "r": 600}, {"l": "irrefuehrend", "t": "irrefuehrend", "p": "uebung", "s": 3, "g": "transfer", "y": "bedingung", "f": {"text": "Zwei Säulen zeigen 40 und 50 Punkte. Bei welchem Achsenanfang (ganze Zahl von 0 bis 39) sieht die zweite Säule mindestens dreimal so hoch aus wie die erste?", "felder": [{"art": "ganz"}]}, "o": {"bedingungen": [{"name": "Achsenanfang von 0 bis 39", "pruefe": ["und", [">=", "$1", 0], ["<=", "$1", 39]], "zeige": "$1", "hinweis": "Dein Achsenanfang ist {}."}, {"name": "zweite Säule mindestens dreimal so hoch", "pruefe": [">=", ["-", 50, "$1"], ["*", 3, ["-", 40, "$1"]]], "zeige": ["/", ["-", 50, "$1"], ["-", 40, "$1"]], "hinweis": "Bei dir ist die zweite Säule {}-mal so hoch wie die erste."}], "beispiel": [35], "gut": [[39], [36]], "gegenbeispiele": [{"werte": [40], "verletzt": "Achsenanfang von 0 bis 39"}, {"werte": [30], "verletzt": "zweite Säule mindestens dreimal so hoch"}, {"werte": [0], "verletzt": "zweite Säule mindestens dreimal so hoch"}]}, "h": "Die sichtbare Höhe ist der Wert minus der Achsenanfang.", "w": "Beginnt die Achse bei 35, sind die Säulen 5 und 15 hoch – das Dreifache. Jeder Anfang von 35 bis 39 passt.", "form": "viele_antworten", "zaehlt": "ja", "r": 601}]$auf$::jsonb),
    (16, 'funktionen.grundbegriffe', 742, 20, $auf$[{"l": "funktionswert", "t": "funktionswert", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "f(x) = x² − 3x. Berechne f(−2) in Schritten: (−2)² = ①. −3 · (−2) = ②. Zusammen: f(−2) = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 6, 10]}, "h": "Setze −2 in Klammern ein.", "w": "(−2)² = 4. −3 · (−2) = 6. Zusammen 4 + 6 = 10.", "form": "lueckenweg", "zaehlt": "nein", "r": 743}, {"l": "eindeutig", "t": "eindeutig", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Jeder Person wird ihre Telefonnummer zugeordnet. Herr Kim hat zwei Nummern. Ist diese Zuordnung eine Funktion?"}, "a": ["Ja, jede Nummer gehört zu genau einer Person.", "Nein, zu Herrn Kim gehören zwei verschiedene Ausgaben.", "Ja, es gibt mehr Nummern als Personen.", "Nein, weil man mit Telefonnummern nicht rechnet."], "o": {"index": 1}, "h": "Was ist hier die Eingabe, was die Ausgabe?", "w": "Eingabe ist die Person, Ausgabe die Nummer. Herr Kim hat zwei Ausgaben – also keine Funktion.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 744}, {"l": "stelle", "t": "stelle", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "f(x) = 2x + 1. Gesucht ist das x mit f(x) = 9. Was tust du?"}, "a": ["2x + 1 = 9 nach x auflösen", "9 für x einsetzen", "f(0) berechnen"], "o": {"index": 0}, "h": "Die 9 ist das Ergebnis, nicht die Eingabe.", "w": "Das Ergebnis ist gegeben. Du löst 2x + 1 = 9: x = 4.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 745}, {"l": "stelle", "t": "stelle", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "f(x) = 4x − 6. Für welches x ist f(x) = 14? Plus 6 auf beiden Seiten: 4x = ①. Geteilt durch 4: x = ②. Zusatzrechnung: Eine Stelle weiter rechts, bei x = ② + 1, ist f(② + 1) = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [20, 5, 18]}, "h": "Das Ergebnis steht rechts vom Gleichheitszeichen.", "w": "4x = 20, x = 5. Die Probe f(5) = 14 stimmt. Zusatzrechnung: Bei x = 6 ist f(6) = 4 · 6 − 6 = 18.", "form": "lueckenweg", "zaehlt": "nein", "r": 746}, {"l": "wertetabelle", "t": "wertetabelle", "p": "uebung", "s": 2, "g": "darstellung", "y": "luecken", "f": {"text": "Die Wertetabelle gehört zu einer Funktion der Form f(x) = a · x + b. Bestimme a und b.", "schablone": "a = □; b = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ).", "grafik": {"typ": "tabelle", "kopf": ["x", "0", "1", "2", "3"], "zeilen": [["f(x)", "−4", "−1", "2", "5"]]}}, "o": {"werte": [3, -4]}, "h": "b steht bei x = 0. a ist der Schritt von einer Spalte zur nächsten.", "w": "Bei x = 0 steht −4, also b = −4. Von Spalte zu Spalte kommen 3 dazu, also a = 3. Probe: 3 · 3 − 4 = 5.", "form": "bruecke", "zaehlt": "ja", "r": 747}, {"l": "wertetabelle", "t": "wertetabelle", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "f(x) = 10 − 3x. In der Wertetabelle steht unter einem x der Wert −5. Welches x ist das?"}, "o": {"wert": 5}, "h": "Der Wert −5 ist das Ergebnis. Löse 10 − 3x = −5.", "w": "10 − 3x = −5. Minus 10: −3x = −15. Geteilt durch −3: x = 5.", "form": "umkehren", "zaehlt": "ja", "r": 748}, {"l": "graph_lesen", "t": "graph_lesen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Lies am Graphen ab: Für welches x gilt f(x) = 3?", "grafik": {"typ": "koordinaten", "x": [-1, 4], "y": [-3, 7], "graphen": [{"art": "linear", "m": 2, "t": -1, "name": "f"}]}}, "o": {"wert": 2}, "h": "Geh von der 3 auf der y-Achse waagrecht zum Graphen, dann senkrecht zur x-Achse.", "w": "Auf der Höhe y = 3 trifft man den Graphen bei x = 2.", "form": "umkehren", "zaehlt": "ja", "r": 749}, {"l": "graph_lesen", "t": "graph_lesen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Wie viele x-Werte gehören am Graphen zum y-Wert 1?", "grafik": {"typ": "koordinaten", "x": [-4, 4], "y": [-4, 6], "graphen": [{"art": "poly", "k": [-3, 0, 1], "name": "f"}]}}, "o": {"wert": 2}, "h": "Zieh in Gedanken eine waagrechte Linie auf der Höhe y = 1.", "w": "Die waagrechte Linie bei y = 1 trifft den Graphen zweimal: bei x = −2 und bei x = 2.", "form": "bruecke", "zaehlt": "ja", "r": 750}, {"l": "nullstellen", "t": "nullstellen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "Nullstelle von f(x) = 3x − 12 auf zwei Wegen. Weg A: 3x − 12 = 0 lösen. Weg B: Werte ausrechnen – f(3) = ①, f(4) = ②. Die Nullstelle ist x = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-3, 0, 4]}, "h": "An der Nullstelle ist der Funktionswert 0.", "w": "f(3) = −3, f(4) = 0. Die Nullstelle ist x = 4. Weg A: 3x = 12, x = 4.", "form": "zwei_wege", "zaehlt": "ja", "r": 751}, {"l": "mengen", "t": "mengen", "p": "uebung", "s": 2, "g": "umkehr", "y": "luecken", "f": {"text": "f(x) = 2x + 1 hat die Wertemenge W = {3; 7; 11}. Aus welchen drei Zahlen besteht die Definitionsmenge? Kleinste zuerst.", "schablone": "D = {□; □; □}", "hinweis": "Kleinste Zahl zuerst."}, "o": {"werte": [1, 3, 5]}, "h": "Zu jedem Wert aus W suchst du das x. Löse 2x + 1 = 3 und so weiter.", "w": "2x + 1 = 3 gibt x = 1. 2x + 1 = 7 gibt x = 3. 2x + 1 = 11 gibt x = 5.", "form": "umkehren", "zaehlt": "ja", "r": 752}, {"l": "sachzusammenhang", "t": "sachzusammenhang", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Ein Schwimmbad kostet 3 € Eintritt und dazu 2 € je Stunde. Welcher Term gibt den Preis für x Stunden an?"}, "a": ["3x + 2", "5x", "2 · (x + 3)", "2x + 3"], "o": {"index": 3}, "h": "Erst die feste Größe, dann die Änderung je Stunde.", "w": "Fest sind 3 €. Je Stunde kommen 2 € dazu: 2x + 3. Probe für 4 Stunden: 2 · 4 + 3 = 11 €.", "form": "bruecke", "zaehlt": "ja", "r": 753}, {"l": "punkt_graph", "t": "punkt_graph", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Liegt P(−2 | 7) auf dem Graphen von f(x) = x² + 3? Mia rechnet: −2² + 3 = −4 + 3 = −1 und sagt Nein. Was stimmt?"}, "a": ["Mia hat recht: P liegt nicht auf dem Graphen.", "P liegt nicht auf dem Graphen, denn (−2)² + 3 = 1.", "Das lässt sich ohne Zeichnung nicht entscheiden.", "P liegt auf dem Graphen, denn (−2)² + 3 = 7."], "o": {"index": 3}, "h": "Wie setzt man eine negative Zahl ein?", "w": "Negative Zahlen werden in Klammern eingesetzt: (−2)² = 4. Also f(−2) = 4 + 3 = 7. P liegt auf dem Graphen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 754}, {"l": "punkt_graph", "t": "punkt_graph", "p": "uebung", "s": 3, "g": "parameter", "y": "zahl", "f": {"text": "Für welches t liegt der Punkt P(2 | 9) auf dem Graphen von f(x) = 3x + t?"}, "o": {"wert": 3}, "h": "Setze x = 2 ein. Das Ergebnis soll 9 sein.", "w": "3 · 2 + t = 9, also 6 + t = 9 und t = 3.", "form": "umkehren", "zaehlt": "ja", "r": 755}, {"l": "sachzusammenhang", "t": "sachzusammenhang", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Kerze ist am Anfang 18 cm hoch und brennt gleichmäßig ab. Nach 4 Stunden ist sie noch 12 cm hoch. Nach wie vielen Stunden (vom Anfang an) ist sie ganz abgebrannt?"}, "o": {"wert": 12, "einheit": "h"}, "h": "Wie viele Zentimeter brennen in einer Stunde ab? Wann ist die Höhe 0?", "w": "In 4 Stunden 6 cm, also 1,5 cm je Stunde. Höhe: 18 − 1,5x. Null bei 18 : 1,5 = 12 Stunden.", "form": "umkehren", "zaehlt": "ja", "r": 756}, {"l": "eindeutig", "t": "eindeutig", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Im Koordinatensystem ist ein Kreis gezeichnet. Ist das der Graph einer Funktion?", "grafik": {"typ": "koordinaten", "x": [-3, 5], "y": [-4, 4], "kreise": [{"m": [1, 0], "r": 3, "name": "k"}]}}, "a": ["Nein, zu x = 1 gehören zwei y-Werte: 3 und −3.", "Ja, zu jedem y gehört ein x.", "Ja, die Linie ist geschlossen.", "Nein, weil ein Kreis keine Gleichung hat."], "o": {"index": 0}, "h": "Geh von einem x aus senkrecht nach oben und unten. Wie oft triffst du die Linie?", "w": "Über x = 1 liegen zwei Punkte der Linie: (1 | 3) und (1 | −3). Eine Eingabe mit zwei Ausgaben – keine Funktion.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 757}, {"l": "funktionswert", "t": "funktionswert", "p": "uebung", "s": 1, "g": "direkt", "y": "bedingung", "f": {"text": "f(x) = 2x − 7. Nenne zuerst ein x, für das f(x) negativ ist, und dann ein x, für das f(x) größer als 10 ist.", "felder": [{"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "erstes x: f(x) ist negativ", "pruefe": ["<", ["-", ["*", 2, "$1"], 7], 0], "zeige": ["-", ["*", 2, "$1"], 7], "hinweis": "Für dein erstes x ist f(x) = {}."}, {"name": "zweites x: f(x) ist größer als 10", "pruefe": [">", ["-", ["*", 2, "$2"], 7], 10], "zeige": ["-", ["*", 2, "$2"], 7], "hinweis": "Für dein zweites x ist f(x) = {}."}], "beispiel": [0, 10], "gut": [[-5, 9], [3, "8,6"]], "gegenbeispiele": [{"werte": [4, 10], "verletzt": "erstes x: f(x) ist negativ"}, {"werte": [0, 8], "verletzt": "zweites x: f(x) ist größer als 10"}, {"werte": ["3,5", 10], "verletzt": "erstes x: f(x) ist negativ"}]}, "h": "Setze dein x ein und rechne aus.", "w": "f(0) = −7 ist negativ. f(10) = 13 ist größer als 10.", "form": "viele_antworten", "zaehlt": "ja", "r": 758}, {"l": "punkt_graph", "t": "punkt_graph", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Nenne zwei verschiedene Punkte auf dem Graphen von f(x) = x² − 4. Mindestens einer soll unterhalb der x-Achse liegen. Reihenfolge der Felder: x und y des ersten Punkts, x und y des zweiten Punkts.", "felder": [{"art": "rational"}, {"art": "rational"}, {"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "erster Punkt liegt auf dem Graphen", "pruefe": ["=", "$2", ["-", ["hoch", "$1", 2], 4]], "zeige": ["-", ["hoch", "$1", 2], 4], "hinweis": "Für dein erstes x ist f(x) = {}."}, {"name": "zweiter Punkt liegt auf dem Graphen", "pruefe": ["=", "$4", ["-", ["hoch", "$3", 2], 4]], "zeige": ["-", ["hoch", "$3", 2], 4], "hinweis": "Für dein zweites x ist f(x) = {}."}, {"name": "verschiedene Punkte", "pruefe": ["!=", "$1", "$3"], "hinweis": "Du hast zweimal denselben Punkt genannt."}, {"name": "einer unterhalb der x-Achse", "pruefe": ["oder", ["<", "$2", 0], ["<", "$4", 0]], "hinweis": "Keiner deiner Punkte liegt unterhalb der x-Achse."}], "beispiel": [0, -4, 3, 5], "gut": [[1, -3, -1, -3], ["0,5", "-3,75", 2, 0]], "gegenbeispiele": [{"werte": [0, 4, 3, 5], "verletzt": "erster Punkt liegt auf dem Graphen"}, {"werte": [0, -4, 3, 6], "verletzt": "zweiter Punkt liegt auf dem Graphen"}, {"werte": [3, 5, 3, 5], "verletzt": "verschiedene Punkte"}, {"werte": [3, 5, -3, 5], "verletzt": "einer unterhalb der x-Achse"}]}, "h": "Wähle ein x und rechne y = x² − 4 aus.", "w": "Zum Beispiel (0 | −4) und (3 | 5): 0² − 4 = −4 und 3² − 4 = 5. Unterhalb der x-Achse liegt ein Punkt, wenn y negativ ist.", "form": "viele_antworten", "zaehlt": "ja", "r": 759}, {"l": "eindeutig", "t": "eindeutig", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Eine Tabelle enthält die Paare (1 | 4) und (2 | 5). Nenne ein drittes Paar (x | y), mit dem die Tabelle KEINE Funktion mehr beschreibt.", "felder": [{"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "mit dem Paar ist es keine Funktion", "pruefe": ["oder", ["und", ["=", "$1", 1], ["!=", "$2", 4]], ["und", ["=", "$1", 2], ["!=", "$2", 5]]], "hinweis": "Mit deinem Paar hat immer noch jede Eingabe genau eine Ausgabe."}], "beispiel": [1, 7], "gut": [[2, 0], [1, -4]], "gegenbeispiele": [{"werte": [3, 4], "verletzt": "mit dem Paar ist es keine Funktion"}, {"werte": [1, 4], "verletzt": "mit dem Paar ist es keine Funktion"}, {"werte": [4, 1], "verletzt": "mit dem Paar ist es keine Funktion"}]}, "h": "Wann ist eine Zuordnung keine Funktion?", "w": "Eine Eingabe braucht zwei verschiedene Ausgaben: zum Beispiel (1 | 7) neben (1 | 4).", "form": "viele_antworten", "zaehlt": "ja", "r": 760}, {"l": "nullstellen", "t": "nullstellen", "p": "uebung", "s": 3, "g": "parameter", "y": "bedingung", "f": {"text": "Setze m und t so ein, dass f(x) = m · x + t die Nullstelle x = 3 hat und f(0) positiv ist.", "felder": [{"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "f(0) ist positiv", "pruefe": [">", "$2", 0], "zeige": "$2", "hinweis": "Bei dir ist f(0) = {}."}, {"name": "Nullstelle bei x = 3", "pruefe": ["=", ["+", ["*", 3, "$1"], "$2"], 0], "zeige": ["+", ["*", 3, "$1"], "$2"], "hinweis": "Bei dir ist f(3) = {}."}], "beispiel": [-2, 6], "gut": [[-1, 3], ["-0,5", "1,5"]], "gegenbeispiele": [{"werte": [2, -6], "verletzt": "f(0) ist positiv"}, {"werte": [-2, 5], "verletzt": "Nullstelle bei x = 3"}, {"werte": [2, 6], "verletzt": "Nullstelle bei x = 3"}]}, "h": "Was bedeutet Nullstelle? Setze x = 3 ein.", "w": "f(3) = 3m + t muss 0 sein, und t = f(0) muss positiv sein. Zum Beispiel m = −2 und t = 6.", "form": "viele_antworten", "zaehlt": "ja", "r": 761}, {"l": "mengen", "t": "mengen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "bedingung", "f": {"text": "f(x) = 12/(x − a). Wähle eine negative Zahl a und ein x so, dass f(x) = 4 ist. Reihenfolge der Felder: a, x.", "felder": [{"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "a ist negativ", "pruefe": ["<", "$1", 0], "zeige": "$1", "hinweis": "Dein a ist {}."}, {"name": "Term ist für dein x definiert", "pruefe": ["!=", "$2", "$1"], "hinweis": "Für dein x ist der Nenner null. Der Term ist dort nicht definiert."}, {"name": "f(x) = 4", "pruefe": ["=", 12, ["*", 4, ["-", "$2", "$1"]]], "zeige": ["/", 12, ["-", "$2", "$1"]], "hinweis": "Bei dir ist f(x) = {}."}], "beispiel": [-1, 2], "gut": [[-3, 0], ["-0,5", "2,5"]], "gegenbeispiele": [{"werte": [1, 4], "verletzt": "a ist negativ"}, {"werte": [-1, -1], "verletzt": "Term ist für dein x definiert"}, {"werte": [-1, 3], "verletzt": "f(x) = 4"}, {"werte": [-3, 3], "verletzt": "f(x) = 4"}]}, "h": "Welchen Wert muss der Nenner haben, damit 12 durch ihn 4 ergibt?", "w": "Der Nenner x − a muss 3 sein. Mit a = −1 ist x = 2: 12/(2 + 1) = 4.", "form": "viele_antworten", "zaehlt": "ja", "r": 762}]$auf$::jsonb),
    (50, 'groessen.einheiten', 648, 19, $auf$[{"l": "laenge", "t": "laenge", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "3,4 km in Meter: 1 km = ① m, also 3,4 km = ② m.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [1000, 3400]}, "h": "In die kleinere Einheit nimmst du mal.", "w": "1 km = 1 000 m. 3,4 · 1 000 = 3 400 m.", "form": "lueckenweg", "zaehlt": "nein", "r": 649}, {"l": "zeit", "t": "zeit", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Von 9:40 Uhr bis 11:15 Uhr: Bis 10:00 Uhr sind es ① min. Von 10:00 Uhr bis 11:15 Uhr sind es ② min. Zusammen: ③ min.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [20, 75, 95]}, "h": "Rechne erst bis zur vollen Stunde.", "w": "Bis 10:00 Uhr 20 min, dann 1 h 15 min = 75 min. Zusammen 95 min.", "form": "lueckenweg", "zaehlt": "nein", "r": 650}, {"l": "schaetzen", "t": "schaetzen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du sollst die Höhe eines Zimmers schätzen. Welche Bezugsgröße hilft dir?"}, "a": ["eine Tür (etwa 2 m hoch)", "eine Tafel Schokolade (100 g)", "eine Schulstunde (45 min)", "eine Packung Milch (1 Liter)"], "o": {"index": 0}, "h": "Die Bezugsgröße muss dieselbe Art von Größe sein.", "w": "Die Höhe ist eine Länge. Die Tür ist etwa 2 m hoch; das Zimmer ist etwas höher, etwa 2,50 m.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 651}, {"l": "kommaschreibweise", "t": "kommaschreibweise", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Mia schreibt: 4 m 7 cm = 4,7 m. Was stimmt?"}, "a": ["Mia hat recht.", "Richtig ist 47 m.", "Richtig ist 4,007 m.", "7 cm sind 0,07 m. Richtig ist 4,07 m."], "o": {"index": 3}, "h": "1 cm ist ein Hundertstel Meter – zwei Stellen hinter dem Komma.", "w": "1 cm ist ein Hundertstel Meter. 7 cm = 0,07 m, also 4,07 m. 4,7 m wären 4 m 70 cm.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 652}, {"l": "rechnen", "t": "rechnen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du sollst 2,5 kg + 750 g rechnen. Was tust du zuerst?"}, "a": ["2,5 + 750 rechnen", "750 durch 2,5 teilen", "das Komma weglassen", "beide Größen in dieselbe Einheit bringen"], "o": {"index": 3}, "h": "Vor plus und minus brauchen beide Größen dieselbe Einheit.", "w": "Erst umrechnen: 2,5 kg = 2 500 g. Dann 2 500 g + 750 g = 3 250 g.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 653}, {"l": "masse", "t": "masse", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "□ g + 350 g = 1,2 kg. Welche Zahl gehört in das Kästchen?"}, "o": {"wert": 850, "einheit": "g"}, "h": "Bring erst alles auf Gramm.", "w": "1,2 kg = 1 200 g. 1 200 − 350 = 850.", "form": "umkehren", "zaehlt": "ja", "r": 654}, {"l": "rechnen", "t": "rechnen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "1,5 m − 85 cm auf zwei Wegen. Weg A in cm: 150 cm − 85 cm = ① cm. Weg B in mm: 1 500 mm − 850 mm = ② mm.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [65, 650]}, "h": "Beide Wege müssen dieselbe Länge ergeben – einmal in cm, einmal in mm.", "w": "150 − 85 = 65 cm. In Millimetern: 1 500 − 850 = 650 mm. 650 mm sind 65 cm, also dasselbe.", "form": "zwei_wege", "zaehlt": "ja", "r": 655}, {"l": "kommaschreibweise", "t": "kommaschreibweise", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Schreibe 3 kg 40 g als Kommazahl in Kilogramm."}, "o": {"wert": 3.04, "einheit": "kg"}, "h": "1 g ist ein Tausendstel Kilogramm – drei Stellen hinter dem Komma.", "w": "40 g = 0,040 kg. Also 3,040 kg = 3,04 kg.", "form": "bruecke", "zaehlt": "ja", "r": 656}, {"l": "laenge", "t": "laenge", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Welche Länge ist am größten?"}, "a": ["0,5 km", "480 m", "51 000 cm", "5 300 dm"], "o": {"index": 3}, "h": "Rechne alle vier in dieselbe Einheit um.", "w": "In Metern: 500 m, 480 m, 510 m und 530 m. Am größten sind 5 300 dm.", "form": "bruecke", "zaehlt": "ja", "r": 657}, {"l": "laenge", "t": "laenge", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Von einem 1,2 m langen Band werden Stücke von je 15 cm abgeschnitten. Wie viele Stücke werden es?"}, "o": {"wert": 8}, "h": "Bring beide Längen auf dieselbe Einheit.", "w": "1,2 m = 120 cm. 120 : 15 = 8 Stücke.", "form": "anwenden", "zaehlt": "ja", "r": 658}, {"l": "massstab", "t": "massstab", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Zwei Orte liegen 4 km auseinander. Wie viele Zentimeter sind das auf einer Karte im Maßstab 1 : 50 000?"}, "o": {"wert": 8}, "h": "Rechne die 4 km erst in Zentimeter um. Auf der Karte ist alles 50 000-mal kleiner.", "w": "4 km = 400 000 cm. 400 000 : 50 000 = 8 cm.", "form": "umkehren", "zaehlt": "ja", "r": 659}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Auf einem Schild steht: „Brücke bis 3,5 t“. Der leere Lieferwagen wiegt 2 800 kg; dazu kommen 900 kg Ladung. Darf er über die Brücke fahren?"}, "a": ["Ja, 3 700 kg sind weniger als 35 000 kg.", "Nein, er wiegt zusammen 3 700 kg. Erlaubt sind 3 500 kg.", "Ja, 2 800 kg sind weniger als 3,5 t.", "Nein, er wiegt 37 t."], "o": {"index": 1}, "h": "Bring beide Angaben auf dieselbe Einheit.", "w": "2 800 kg + 900 kg = 3 700 kg. 3,5 t = 3 500 kg. Der Wagen ist 200 kg zu schwer.", "form": "anwenden", "zaehlt": "ja", "r": 660}, {"l": "massstab", "t": "massstab", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "Ein Käfer ist in einem Buch im Maßstab 5 : 1 abgebildet und dort 6 cm lang. Jan sagt: „In Wirklichkeit ist er 30 cm lang.“ Wie viele Millimeter ist der Käfer wirklich lang?"}, "o": {"wert": 12, "einheit": "mm"}, "h": "5 : 1 heißt: Das Bild ist 5-mal so groß wie der Käfer.", "w": "Das Bild ist vergrößert. Wirklich: 6 cm : 5 = 1,2 cm = 12 mm.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 661}, {"l": "zeit", "t": "zeit", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "luecken", "f": {"text": "Ein Film dauert 1 h 50 min und endet um 21:15 Uhr. Wann hat er begonnen?", "schablone": "□:□ Uhr", "hinweis": "Erst die Stunde, dann die Minuten."}, "o": {"werte": [19, 25]}, "h": "Geh erst 2 Stunden zurück und dann 10 Minuten wieder vor.", "w": "2 Stunden vor 21:15 Uhr ist 19:15 Uhr. Der Film ist 10 Minuten kürzer, also begann er um 19:25 Uhr.", "form": "umkehren", "zaehlt": "ja", "r": 662}, {"l": "laenge", "t": "laenge", "p": "uebung", "s": 1, "g": "direkt", "y": "bedingung", "f": {"text": "Nenne eine Länge in ganzen Zentimetern, die größer als 1,2 m und kleiner als 1,3 m ist.", "felder": [{"art": "ganz"}]}, "o": {"bedingungen": [{"name": "größer als 1,2 m", "pruefe": [">", "$1", 120], "zeige": "$1", "hinweis": "Deine Länge ist {} cm."}, {"name": "kleiner als 1,3 m", "pruefe": ["<", "$1", 130], "zeige": "$1", "hinweis": "Deine Länge ist {} cm."}], "beispiel": [125], "gut": [[121], [129]], "gegenbeispiele": [{"werte": [12], "verletzt": "größer als 1,2 m"}, {"werte": [130], "verletzt": "kleiner als 1,3 m"}, {"werte": [1250], "verletzt": "kleiner als 1,3 m"}, {"werte": [120], "verletzt": "größer als 1,2 m"}]}, "h": "Rechne beide Grenzen in Zentimeter um.", "w": "1,2 m = 120 cm und 1,3 m = 130 cm. Es passt jede Zahl von 121 bis 129.", "form": "viele_antworten", "zaehlt": "ja", "r": 663}, {"l": "masse", "t": "masse", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Zwei Pakete wiegen zusammen genau 2 kg. Das erste ist schwerer als 1,2 kg. Nenne beide Gewichte in Gramm.", "felder": [{"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "zusammen 2 kg", "pruefe": ["=", ["summe", "$alle"], 2000], "zeige": ["summe", "$alle"], "hinweis": "Zusammen wiegen deine Pakete {} g."}, {"name": "erstes Paket schwerer als 1,2 kg", "pruefe": [">", "$1", 1200], "zeige": "$1", "hinweis": "Dein erstes Paket wiegt {} g."}, {"name": "jed